import type { UnitCode } from '../domain/catalog'

const variant = (id: string, label: string, form = label.toLowerCase()) => ({ id: `variant-${id}`, label, form })
const ingredient = (id: string, displayName: string, baseUnit: UnitCode, variants = [variant(`${id}-default`, 'Standard')], aliases: string[] = []) => ({ id: `ingredient-${id}`, displayName, baseUnit, aliases, variants })
const amount = (value: number, unit: UnitCode, approximate = false) => ({ amount: value, unit, approximate })
type RequirementOptions = {
  preparation?: string
  optional?: boolean
  nonQuantified?: 'to-taste' | 'as-needed' | 'for-serving'
  confidence?: 'reviewed' | 'needs-review'
  reviewNote?: string
  alternatives?: { label: string; ingredientId: string; variantId: string; quantity: ReturnType<typeof amount> | null }[]
}
const requirement = (recipe: string, id: string, originalText: string, ingredientId: string, variantId: string, quantity: ReturnType<typeof amount> | null, options: RequirementOptions = {}) => ({
  id: `requirement-${recipe}-${id}`,
  originalText,
  canonicalIngredientId: `ingredient-${ingredientId}`,
  variantId: `variant-${variantId}`,
  quantity,
  nonQuantified: options.nonQuantified ?? null,
  preparation: options.preparation ?? null,
  optional: options.optional ?? false,
  confidence: options.confidence ?? 'reviewed',
  reviewNote: options.reviewNote ?? null,
  sourceRange: null,
  alternatives: (options.alternatives ?? []).map((alternative) => ({ label: alternative.label, canonicalIngredientId: `ingredient-${alternative.ingredientId}`, variantId: `variant-${alternative.variantId}`, quantity: alternative.quantity })),
  sourcePackage: null,
})
const mealYield = (servings: number, label = `${servings} servings`, range: { min: number; max: number } | null = null) => ({ source: { kind: 'meal-servings' as const, amount: range ? null : servings, range, unit: 'servings', label }, planningServings: { default: servings, range, assumption: range ? 'Planning default is the midpoint of the source range.' : null } })
const countYield = (output: number, unit: string, planningServings: number, assumption: string) => ({ source: { kind: 'countable-output' as const, amount: output, range: null, unit, label: `${output} ${unit}` }, planningServings: { default: planningServings, range: null, assumption } })
const source = (url: string, rating: number | null, reviewCount: number | null, rationale: string, author: string | null = 'Beth Moncel') => ({ publisher: 'Budget Bytes', author, url, checkedAt: '2026-11-13', selectionRationale: rationale, rating, reviewCount })
const review = { status: 'source-reviewed' as const, reviewedAt: '2026-11-13', ingredientCompletenessReviewed: true as const, methodIndependentlyWritten: true as const }

